   "solution":"Это инцидент безопасности: данные карт попали туда, где их быть не должно, и разошлись дальше — во внешний сервис и в резервные копии журналов. Порядок действий отличается от обычного дефекта. Первое: сообщить ответственному за безопасность немедленно, потому что решения о чистке и уведомлениях принимает не тестировщик. Второе: зафиксировать факт, не копируя данные карты никуда — в тикете указывается место в коде и идентификатор записи, а не сам номер. Третье: прекратить запись тела запроса, оставив только идентификаторы и коды ответа. Четвёртое: оценить масштаб — сколько записей, за какой период, кто имел доступ, ушло ли во внешний сервис, попало ли в резервные копии. Пятое: проверить остальные следы, потому что если тело пишется при ошибке валидации, оно почти наверняка пишется и в трассировках, и в отчётах о падениях, и в аналитике на клиенте. Хорошая практика после разбора — постоянная проверка: тест, который проводит платёж тестовой картой и ищет её номер во всех журналах.",
