   "solution":"Задержка объясняется постепенным включением: изменение доходило до всех пользователей не мгновенно, поэтому доля отказов росла плавно и пересекла порог заметности через 45 минут. Концентрация на одном эмитенте — сильная подсказка: наш код одинаков для всех, значит дело в данных, которые этот эмитент проверяет строже. Сравнение тел запросов до и после показывает изменение в адресе плательщика: например, поле стало передаваться пустым или в другом формате, а этот эмитент отклоняет такие операции. Правильный порядок — сначала откат, потому что потери идут каждую минуту и изменение не критично для бизнеса, а уже потом разбор на стенде. К провайдеру обращаются с конкретикой: идентификаторы операций, время, код отказа — без этого поддержка ответит общими словами. В выводы стоит записать проверку: сравнение отправляемых данных до и после изменений в оформлении заказа, потому что глазами такие расхождения не видны.",
