   "scenario":"Магазин добавил приём оплаты в валюте без дробной части. На тестовом стенде заказ на 5000 единиц этой валюты уходит провайдеру как 5000, а в письме покупателю и в интерфейсе отображается как 50.00. При оплате в евро расхождений нет. Разработчик говорит, что сумма везде хранится в минорных единицах и делится на сто только при выводе.",
   "solution":"Провайдеру уходит верное значение: для валюты без дробной части минорная единица совпадает с основной, поэтому 5000 означает 5000. Ошибка в обратном преобразовании — деление на сто зашито в код вывода без учёта валюты. В евро это совпадает с правдой, поэтому дефект и не замечали. Чинить нужно не одно место: то же преобразование почти наверняка используется в письме, в карточке заказа, в отчётах, в интерфейсе поддержки и при расчёте суммы возврата — последнее самое опасное, потому что вернуть можно в сто раз меньше или больше. Правильное решение — брать число знаков из справочника валют, а не из предположения. В набор проверок добавляются валюта без дробной части и валюта с тремя знаками: они ломают код с обеих сторон. Отдельно проверяется сверка с отчётом провайдера — там расхождение видно сразу и по всем операциям.",
