   "level":3,
   "model_answer_en":"First I'd check the scale: how many users and how much money, using the logs and the database rather than a guess. Then I'd report it immediately in the incident channel, with the exact steps to reproduce and the affected time window — waiting to look confident costs money. I'd save the evidence: request identifiers, screenshots, the rows in the ledger. Then I'd suggest a temporary workaround, for example switching off that payment method, while the fix is being prepared.",
   "model_answer_ru":"Сначала масштаб: сколько пользователей и сколько денег — по логам и базе, а не на глаз. Потом сразу сообщаю в канал инцидентов: точные шаги воспроизведения и затронутый период. Ждать, чтобы выглядеть увереннее, — это терять деньги. Сохраняю доказательства: идентификаторы запросов, скриншоты, строки в журнале операций. Дальше предлагаю обходной путь, например временно отключить этот способ оплаты, пока готовится исправление.",
   "prompt_en":"You found a bug in production that costs money. What do you do?",
