   "category":"Технический вопрос",
   "hint":"Пример двойного списания, ключ идемпотентности, что считается одинаковым запросом.",
   "id":"ed-qa-003",
   "keywords":[
    "the same key",
    "charged twice",
    "safe to retry"
   ],
   "level":3,
   "model_answer_en":"Retries are safe only if the server can tell that it's the same request. If the network drops after the bank approved the payment, our retry looks like a brand new payment, and the customer is charged twice. That's why the client sends an idempotency key: the same key means the same operation, so the server returns the original result instead of charging again. Without that key, a retry is not a retry — it's a second payment.",
   "model_answer_ru":"Повторы безопасны только если сервер понимает, что это тот же самый запрос. Если связь оборвалась после одобрения банком, наш повтор выглядит как новый платёж, и с клиента списывают дважды. Поэтому клиент присылает ключ идемпотентности: одинаковый ключ означает одну и ту же операцию, и сервер возвращает прежний результат вместо нового списания. Без ключа повтор — это не повтор, а второй платёж.",
   "prompt_en":"Explain idempotency to a developer who says retries are safe anyway.",
   "prompt_ru":"Объясните идемпотентность разработчику, который считает, что повторы и так безопасны.",
