   "common_confusion":"Путают уровень тестирования с его типом: функциональное или нагрузочное тестирование бывает на любом уровне.",
   "definition_interview":"Модульный уровень проверяет единицу кода в изоляции, интеграционный — взаимодействие частей и внешних систем, системный — поведение продукта целиком, приёмочный — соответствие ожиданиям заказчика. Чем выше уровень, тем дороже и медленнее проверка.",
