   "common_confusion":"Считают дымовой набор урезанным регрессом. Он не урезанный, а другой: в нём только то, без чего продукт бесполезен.",
   "definition_interview":"Дымовой набор короткий и покрывает главные сценарии: если он падает, дальше проверять смысла нет. Регрессионный набор шире и защищает уже сданную функциональность от изменений в соседнем коде.",
