   "answer":"Когда функциональность часто меняется и подробные шаги устаревают быстрее, чем их успевают править, а проверяющий знает систему. Тест-кейсы нужнее там, где проверку выполняет новый человек или где важна точная воспроизводимость.",
   "category":"Тестирование",
