   "aliases":[
    "коды валют",
    "currency code"
   ],
   "answer":"Из справочника валют, а не из предположения о двух знаках. Иначе валюты без дробной части и с тремя знаками ломаются на округлении, а расхождения всплывают уже в сверке с провайдером.",
   "category":"Деньги и валюты",
   "common_confusion":"Считают код валюты просто подписью к сумме. Он определяет точность, а значит и правила округления и хранения.",
   "definition_interview":"Международный реестр валют: буквенный и цифровой код и число знаков после запятой. Служит источником правды о точности суммы, поэтому число знаков берут из него, а не из вёрстки.",
   "definition_simple":"Стандарт трёхбуквенных кодов валют: EUR, USD, PLN.",
   "difficulty":2,
   "example":"EUR — два знака, JPY — ноль, KWD — три. Приложение, которое везде выводит две цифры после запятой, показывает японскую сумму неверно.",
