   "answer":"Беру суммы, которые не делятся нацело: скидка в процентах, деление на три позиции, налог. Сверяю, что сумма строк равна итогу, что итог совпадает с суммой в платёжном провайдере и что полный возврат по частям возвращает ровно исходную сумму.",
   "category":"Деньги и валюты",
   "common_confusion":"Округляют на каждом шаге расчёта. Двойное округление накапливает ошибку, и итог не совпадает с суммой строк.",
   "definition_interview":"Согласованное правило приведения расчётной суммы к точности валюты. Важнее самого правила его единственность: если скидка, налог и комиссия округляются в разных местах по-разному, итог перестаёт сходиться.",
   "definition_simple":"Правило, по которому дробные копейки превращаются в целые, — и место, где деньги теряются.",
   "difficulty":3,
   "example":"Скидка 33% на 10.00 даёт 6.70 при округлении вниз и 6.70 при округлении к ближайшему, но на трёх позициях расхождение уже видно в чеке: сумма позиций не равна итогу заказа.",
