   "answer":"Потому что двоичная дробь не выражает десятичную точно и погрешность накапливается при сложении. Храню в целых минорных единицах или в десятичном типе с фиксированной точностью, а в тестах проверяю итоги по большому числу строк, а не по одной.",
   "category":"Деньги и валюты",
   "common_confusion":"Считают, что округление при выводе решает проблему. Оно прячет расхождение на экране, но не в базе и не в сверке.",
   "definition_interview":"Двоичное представление не может точно выразить большинство десятичных дробей, и погрешность накапливается при сложении. Для денег используют целые числа в минорных единицах или десятичный тип с фиксированной точностью.",
   "definition_simple":"Дробные числа в двоичном виде хранят десятичные суммы неточно, поэтому деньгами так не считают.",
   "difficulty":2,
   "example":"Сложение 0.1 и 0.2 в таком представлении даёт не 0.3, а число с хвостом. На одном платеже незаметно, на дневном отчёте расхождение с провайдером уже видно.",
