   "answer":"Совпадение показанной и списанной суммы с учётом того, кто конвертирует, поведение при задержке между авторизацией и списанием и возврат: он должен вернуть ту же сумму в валюте платежа, а не пересчитанную по новому курсу.",
   "category":"Деньги и валюты",
   "common_confusion":"Считают, что конвертация проверяется одним тестом на пересчёт. Проверять надо согласованность: показанная сумма, списанная и возвращённая.",
   "definition_interview":"Коэффициент пересчёта, применяемый магазином, провайдером или эмитентом. Момент фиксации курса определяет, совпадёт ли списанная сумма с показанной покупателю, а разница между ними — источник претензий и споров.",
