   "answer":"Провожу платёж с тестовой картой и ищу её номер по всем следам: логи приложения и веб-сервера, трассировки, тексты ошибок, отчёты о падениях, аналитика фронтенда. Отдельно проверяю негативные сценарии — при ошибке в лог часто пишут тело запроса целиком.",
   "category":"Данные карт и PCI DSS",
   "common_confusion":"Считают, что раз номер уже есть у провайдера, ничего страшного в его записи в свой лог нет. Утечка из лога — такая же утечка данных карт.",
   "definition_interview":"Основной идентификатор карточного счёта. Относится к данным держателя карты: его хранение допустимо только в защищённом виде и только при обоснованной необходимости, а отображение — в маскированном.",
   "definition_simple":"Номер карты — главное, что нельзя хранить и показывать целиком без крайней необходимости.",
