   "answer":"Три вещи: не использовать настоящие карты в тестовых средах, не прикладывать данные карт к дефектам и скриншотам и следить, чтобы номер и код проверки не попадали в логи и аналитику. Всё остальное — вопрос архитектуры и доступов.",
   "category":"Данные карт и PCI DSS",
   "common_confusion":"Считают стандарт делом безопасников. На тестировщика он влияет напрямую: тестовые данные, логи, доступ к средам и то, что можно приложить к дефекту.",
   "definition_interview":"Стандарт совета платёжных систем: сегментация сети, шифрование передачи, ограничение доступа, журналирование, регулярная проверка защищённости. Объём обязательств зависит от того, как магазин принимает карты.",
