   "answer":"Отправляю два одинаковых запроса с одним ключом и убеждаюсь, что платёж один, а ответы совпадают. Потом — те же данные с разным ключом: должно получиться два платежа. И отдельно тот же ключ с изменённой суммой: провайдер обязан ответить ошибкой, а не тихо применить старый результат.",
   "category":"Интеграции и API",
   "common_confusion":"Генерируют ключ на каждую попытку. Тогда защиты нет: два запроса с разными ключами — два платежа. Ключ обязан быть привязан к намерению, а не к нажатию.",
   "definition_interview":"Идентификатор, который клиент передаёт вместе с операцией создания. Сервер запоминает результат по ключу и на повтор с тем же ключом отдаёт прежний ответ. Это защита от двойного списания при обрывах и повторах.",
