   "short_answer":"Сначала делю на классы эквивалентности: ниже минимума, внутри диапазона, выше максимума. Из каждого беру по значению. Дальше границы, потому что там и сидят ошибки: ноль, единица, двойка и 99 999, 100 000, 100 001. Потом отрицательные проверки: пусто, минус, буквы, дробь с тремя знаками, пробелы. И отдельно смотрю, что происходит на стороне сервера, а не только в интерфейсе: проверка на фронте обходится запросом напрямую, и для платежей это принципиально.",
