   "estimated_minutes":30,
   "example":"Плохо: «Не проходит оплата картой». Хорошо: «Оплата картой Visa в EUR завершается ошибкой 500 при сумме больше 1000». Дальше шаги, идентификатор попытки, время и ответ сервера. Второй вариант берут в работу сразу.",
   "id":"lesson-qa-test-docs",
   "interview_question":"Что обязательно должно быть в баг-репорте?",
