   "short_answer":"Заголовок, по которому понятно, что сломано, без чтения тела. Дальше шаги воспроизведения с понятного начального состояния, ожидаемый и фактический результат, окружение и версия. Для платежей добавляю то, без чего разработчик не найдёт концы: идентификатор операции, точное время с часовым поясом, ответ провайдера. И приложение — запрос с ответом, а не только скриншот. Мне важно, чтобы отчёт был самодостаточным: если человек возьмёт его через неделю, ему не должно понадобиться меня спрашивать.",
