   "estimated_minutes":45,
   "example":"Покупатель видит списание, а заказ не создан. На деле прошла авторизация, а создание заказа упало — и списание не выполнялось. Деньги заморожены и вернутся сами, но клиенту об этом никто не сказал. Дефект не в платеже, а в том, что система не отменила авторизацию.",
