   "short_answer":"Авторизация — это проверка карты и заморозка суммы: банк подтверждает, что деньги есть, и делает их недоступными покупателю. Но продавцу они ещё не ушли. Списание подтверждает операцию, и уже после него запускается перевод, который фактически доходит до продавца ещё позже, при расчёте. Практическая разница огромная: до списания операцию можно отменить, и клиент почти ничего не заметит, а после — только возврат, со своими сроками. И типовой дефект живёт ровно здесь: авторизация прошла, дальше что-то упало, а отмену никто не сделал.",
