   "estimated_minutes":35,
   "example":"Подключили оплату переводом. Тесты прошли: платёж проходит. В продакшене выяснилось, что кнопка отмены заказа пытается снять авторизацию, которой у перевода нет. Заказ отменяется, деньги остаются у продавца.",
