   "short_answer":"Сначала выясняю, как он устроен: есть ли двухшаговая схема с заморозкой или деньги уходят сразу, поддерживается ли частичный возврат, за какое время возвращаются деньги. От этого зависит весь набор проверок. Дальше прохожу полный цикл: оплата, отмена до подтверждения, полный возврат, частичный возврат. Отдельно смотрю отказы — у каждого способа свои коды, и пользователю нужно разное действие. И обязательно проверяю, что уже существующие сценарии отмены и возврата не сломались: обычно они написаны под карты и молча предполагают карточную схему.",
