   "estimated_minutes":40,
   "example":"Пользователь подтвердил оплату, но закрыл вкладку до возврата в магазин. Деньги списаны, заказ не создан: система ждала возврата пользователя, а не уведомления от провайдера. Правильно — опираться на уведомление, а возврат пользователя считать лишь удобством.",
