   "short_answer":"Успешное подтверждение — только один из них, и самый простой. Дальше идут отказ банка, неверный код, закрытое окно и таймаут: это четыре разных исхода, и система должна вести себя по-разному. Отдельно проверяю возврат пользователя после переадресации, потому что там теряется сессия и случаются повторные отправки. И главное, что проверяю всегда: не полагается ли создание заказа на то, что пользователь вернулся в магазин. Опираться нужно на уведомление от провайдера, иначе закрытая вкладка оставляет списание без заказа.",
