   "estimated_minutes":40,
   "example":"Заказ на 1000. Сделали частичный возврат 600, потом ещё 600. Если проверки на суммарный остаток нет, продавец вернёт 1200 при платеже в 1000. Проверяется двумя запросами подряд и находится за минуту.",
