   "short_answer":"Возврат инициирует продавец: сам, добровольно, обычной операцией через провайдера. Чарджбэк инициирует держатель карты через свой банк, и продавец узнаёт об этом уже по факту — сумму списывают, плюс обычно комиссия. Дальше у продавца есть срок, чтобы оспорить, и нужны доказательства: подтверждение доставки, переписка. Отдельно от обоих стоит отмена: она возможна только до списания и просто снимает заморозку. Практический вывод для тестирования — это три разных сценария с разными состояниями, и их нельзя проверять одним.",
