   "short_answer":"Первым делом обхожу интерфейс: отправляю запрос напрямую с теми данными, которые форма не даёт ввести — отрицательная сумма, чужой идентификатор заказа, отсутствующие поля. Очень часто проверка живёт только на фронте. Дальше смотрю не только код ответа, но и тело: платёж может вернуть 200 и содержать отказ. Отдельно проверяю ошибки: отказ карты и сбой интеграции должны различаться, иначе мониторинг будет врать. И обязательно таймаут: если провайдер не ответил, состояние операции неизвестно, и система должна его выяснить, а не решить, что платежа не было.",
