   "estimated_minutes":35,
   "example":"Заказ на 10.00 с тремя позициями и скидкой 10%. Скидка делится между позициями, доли округляются, и сумма долей оказывается на копейку меньше исходной. Оплата проходит верно, а вот полный возврат по частям возвращает 9.99 вместо 10.00 — расхождение находит бухгалтерия через месяц, когда таких заказов накопились десятки.",
