   "short_answer":"Беру суммы, которые не делятся нацело: скидка в процентах, три позиции, налог. Сверяю, что сумма строк равна итогу, итог совпадает с суммой у провайдера, а полный возврат по частям возвращает ровно исходную сумму, причём последний возврат забирает остаток. Отдельно проверяю валюты без дробной части и с тремя знаками: там ломается обратное преобразование. И смотрю в базу — деньги должны храниться целыми минорными единицами или десятичным типом, а не числом с плавающей точкой.",
