   "estimated_minutes":30,
   "example":"Форма оплаты показывает «•••• 4242», но в ответе API поле card_number приходит целиком — экран просто обрезает его на отрисовке. Номер уходит в браузер, в записи сессий и в аналитику, а дефект незаметен при проверке глазами.",
