   "short_answer":"Провожу платёж тестовой картой и ищу её номер по всем следам: журналы приложения и веб-сервера, тексты ошибок, трассировки, отчёты о падениях, ответы API, клиентская аналитика и записи сессий. Особое внимание отказным сценариям — при ошибке в журнал часто пишут тело запроса целиком. Отдельно проверяю, что код проверки карты не сохраняется нигде и не возвращается в ответах. Если нахожу утечку, не копирую номер в тикет: указываю место в коде и иду к ответственному за безопасность, потому что это инцидент, а не рядовой дефект.",
