   "short_answer":"Сначала устанавливаю факт: нахожу операцию в отчёте провайдера по идентификатору и смотрю, списание это или незакрытый резерв. Если списание есть, а у нас промежуточный статус, ищу событие — пришло ли, обработалось ли, была ли ошибка. Клиенту закрываю вопрос сразу, не дожидаясь конца разбора: подтверждаю заказ или возвращаю деньги. Параллельно смотрю масштаб: если таких платежей десятки, это инцидент, и дальше речь уже о восстановлении, а не об одном обращении.",
