   "model_answer_full":"Ценность ответа в первом шаге: уточнение правил до начала проверки. Половина дефектов в частичных возвратах — не ошибки кода, а неопределённость требований по делению скидки и доставки. Дальше стандартная техника: классы, границы, накопительный остаток. Упоминание сверки показывает, что вы понимаете: возврат не заканчивается успешным ответом API.",
