   "model_answer_full":"Вопрос про зрелость, а не про правоту. Ключевой ход — перевести спор из плоскости мнений в плоскость требований и последствий. Эскалация уместна, но как обращение за решением, а не как жалоба. Готовность признать ошибку — сильный сигнал: с таким человеком безопасно спорить, и его дефектам верят больше.",
   "model_answer_short":"Сначала выясняю, расходимся мы в фактах или в трактовке требований. Если в требованиях ничего не сказано, спорить бессмысленно: иду к аналитику или владельцу продукта и прошу решить. Аргументирую последствиями: сколько людей это затронет и во сколько обойдётся. Если оказывается, что я неправа, спокойно закрываю дефект — это нормальная часть работы.",
