   "intent":"Проверка умения говорить на языке бизнеса",
   "model_answer_full":"Проверяется способность переводить техническое в понятное. Ошибка кандидатов — рассказывать про гонки и статусы человеку, которому нужны деньги, клиенты и сроки. Второй важный момент — варианты: «нельзя выпускать» без альтернатив читается как каприз, а два-три сценария превращают вас в собеседника, а не в препятствие.",
   "model_answer_short":"Говорю не про код, а про деньги: при таком дефекте часть платежей уйдёт в двойное списание, это примерно столько-то операций в день и возвраты с обращениями в поддержку. Даю оценку вероятности честно, без запугивания. Предлагаю варианты: выпустить без этой части, выпустить на малой доле трафика и понаблюдать, либо подождать день. Решение оставляю за руководителем — моя задача сделать риск понятным.",
