   "intent":"Проверка способности к разбору собственных ошибок",
   "model_answer_full":"Вопрос проверяет не безошибочность, а зрелость. Ответ «такого не было» звучит неправдоподобно и закрывает тему. Сильная структура: конкретный случай, честный разбор слепой зоны, ваши действия и изменение в процессе. Важно говорить «я», а не «мы»: интервьюеру нужна ваша роль, а не отчёт команды.",
   "model_answer_short":"Пропустили дефект в частичных возвратах: при делении суммы на три позиции терялась копейка, и сумма возвратов не сходилась с платежом. Мы проверяли круглые суммы, поэтому не увидели. Заметили на сверке через неделю. Я разобрала расхождение, помогла собрать список затронутых платежей, а в чек-лист добавила строку про суммы, не делящиеся нацело. С тех пор такие случаи ловятся до релиза.",
