   "intent":"Проверка поведения под давлением",
   "model_answer_full":"Ошибка кандидатов — рассказывать о подвиге: «работал ночью и всё успел». Работодателю интереснее ваш способ принимать решения при нехватке времени. Сильный ответ содержит принцип выбора, письменную передачу риска и результат. Упоминание постепенного выката показывает, что вы думаете об управлении риском, а не только о проверках.",
   "model_answer_short":"Перед новогодним пиком нам дали два дня на проверку нового способа оплаты. Я взяла денежные сценарии и область изменений, остальное выписала как непокрытое и отправила письмом владельцу продукта с оценкой риска. Выпустили на десяти процентах трафика и сутки смотрели долю успешных платежей. Один дефект всплыл на этой доле, починили до полного включения. Вывод: постепенный выкат экономит больше, чем ещё день проверок.",
