   "intent":"Проверка умения отстаивать позицию и уступать",
   "model_answer_full":"Вопрос проверяет две вещи сразу: умеете ли вы аргументировать и умеете ли принимать чужое решение. Сильный ответ содержит цифры, а не ощущения, и явно проговаривает поведение в случае проигрыша: зафиксировать риск и организовать наблюдение. Кандидат, который «всегда прав», настораживает больше, чем тот, кто иногда уступает.",
   "model_answer_short":"Команда хотела выпустить изменение в возвратах без проверки повторной отправки запроса, считая случай редким. Я привела оценку: при обрыве связи это прямой убыток, и таких обрывов у нас в логах несколько десятков в день. Договорились отложить на день и добавить защиту. Если бы решили выпускать, я бы записала риск письменно и настроила наблюдение — спорить дальше смысла нет, решение не моё.",
