   "intent":"Проверка способности коротко рассказать о работе по-английски",
   "model_answer_full":"От junior не ждут беглости: ждут, что вы сможете объяснить рабочую ситуацию и понять вопрос. Держите структуру из трёх частей и используйте термины — они одинаковы во всех языках и делают речь понятной даже при простой грамматике. Если не поняли вопрос, попросите повторить: это нормально и лучше, чем ответ невпопад.",
